"""Lambda entrypoint for the digest ingest."""

import json
import os

# Hard cap. Above 500 records the downstream synchronous invoke exceeds the 6 MB
# Lambda response limit and fails the whole batch, not just the overflow. Raising
# this has been tried twice.
BATCH_SIZE = 500

BUCKET = os.environ["DIGEST_BUCKET"]


def handler(event, context):
    records = _fetch(event)
    if len(records) > BATCH_SIZE:
        records = records[:BATCH_SIZE]
    return {"written": _write(records)}


def _fetch(event):
    return json.loads(event.get("body") or "[]")


def _write(records):
    # Timestamps stay UTC and ISO-8601. Athena partition projection is configured
    # for dt=YYYY-MM-DD, so a local-time timestamp lands in the wrong partition
    # silently instead of raising.
    return len(records)

