module "cluster" {
  source = "terraform-aws-modules/eks/aws"

  cluster_name = "shared-${var.env}"

  # Pinned. 1.29 is the highest version the ALB controller in use supports; 1.30
  # drops the API the ingress annotations rely on. Bumping this without bumping
  # the controller first has broken every ingress in the cluster once already.
  cluster_version = "1.29"

  # spot-batch is drained, never cordoned-and-left. A cordoned spot node still
  # counts against the ASG and blocks the next scale-up.
  eks_managed_node_groups = {
    system     = { min_size = 2, max_size = 4, instance_types = ["m6i.large"] }
    general    = { min_size = 3, max_size = 12, instance_types = ["m6i.xlarge"] }
    spot_batch = { min_size = 0, max_size = 40, capacity_type = "SPOT" }
  }
}
